    "whoMayAvail": "All owners of public or private building/structure who are yet to use/occupy such building/structure or wants to change the type of use or occupancy of their building/structure located within the jurisdiction of the City of San Fernando, La Union",
    "description": "As per provision of the National Building Code of the Philippines (P.D. 1096), the Office of the Building Official grants and issues Certificate of Occupancy to all owners of buildings/structures both public and private that are found to be safe for occupancy, is livable, and has been constructed according to the approved plans and specifications as submitted.\nProcessing of Occupancy Permit could be less than 3 working days for small buildings/structures or simple works and a maximum of 20 working days for big buildings/structures or highly technical works.\nOnly the Building Official can approve and sign Building Permits. Delegation of the authority is allowed only for an absence of more than one (1) month.",
    "summary": "As per provision of the National Building Code of the Philippines (P.D.",
