    "whoMayAvail": "Employees or workers in generally considered offensive and dangerous business establishments",
    "description": "Employees or workers in generally considered offensive and dangerous business establishments\nEmployees and workers in commercial establishments who generally enter or attend to the daily needs of the general public such as but not limited to the following: employees and workers in drugstores, department stores, groceries, supermarkets, beauty salons, barber shops, tailor shops, and dress shops; bank teller, receptionist, receiving clerk in paying outlets of public utilities corporation, except transportation companies; and other commercial establishments whose employees and workers attend to the daily needs of the inquiring or paying public.\nEmployees and workers in food or eatery establishments such as but not limited to the following: Employees and workers in canteen, carinderia, catering services, bakeries, ice cream or ice milk factories, refreshment parlors, restaurants, sari-sari stores, and soda fountains;\nStallholders, employees and workers in public markets;\nPeddlers of cooked or uncooked food; and\nAll other food peddlers, including peddlers of seasonal merchandise.\nEmployees or workers in night or night and day establishments such as but not limited to the following: Workers or employees in bars, boxing stadium, bowling alleys, billiards and pool halls, cinema houses, cabarets and dance halls, cocktail lounges, circuses, carnivals and the like; Day clubs and night clubs, golf clubs, massage clinics, sauna baths or similar establishments, hotels, motels, gym and sports establishments; private detective or watchman security agencies; super clubs and all other business establishments whose business activities are performed and consumed during night time\nAll other employees and persons who exercise their profession, occupation or calling within the jurisdictional limits of the city subject to periodic inspection, surveillance and/or regulations by the City Mayor\nPursuant to City Revenue Code 2018 series of 2018, Persons Governed: The following workers or employees (as cited below), whether working on temporary or permanent basis, shall secure the Individual Work Permit (IWP). Renewal of Individual Work Permit shall start from October to December.",
