    "whoMayAvail": "Document owner of legal age (18 years old or above) or his/her Authorized Representative;",
    "description": "Document owner of legal age (18 years old or above) or his/her Authorized Representative;\nLegal spouse;\nParents;\nChildren (of legal age) of the document owner;\nIf the document owner is a minor and in default of the parents: The guardian appointed by the court;\nThe following persons exercising substitute parental authority in the order indicated pursuant to Article 216 of the Family Code of the Philippines provided that he/she executes and presents an Affidavit of Guardianship stating that he/she is the duly appointed guardian of the minor: The surviving grandparent;\nThe oldest brother or sister, over 21 years old, unless unfit or disqualified;\nThe child’s actual custodian, over 21 years old, unless unfit or disqualified.\nInstitution legally in charge of the minor with authorization from the Regional Director of the Department of Social Welfare and Development;\nThe court or proper public official through their issuance of a subpoena duces tecum and ad testificandum;\nGovernment agencies pursuant to their mandate through a Data Sharing Agreement in accordance with National Privacy Commission Circular No. 16-02;\nLive Birth and Death shall be registered within thirty (30) days from the occurrence of the event. For ordinary marriage, the time for submission of the Certificate of Marriage is within fifteen (15) days following the solemnization of marriage. For marriage exempt from marriage requirement/s, the prescribed period for registration is thirty (30) days at the place where the marriage was solemnized.",
    "summary": "Document owner of legal age (18 years old or above) or his/her Authorized Representative;",
    "fees": "NO FEES AND CHARGES REQUIRED.",
